import{MemeDisplay}from './meme-display.js';import{MemeNavigation}from './meme-navigation.js';import{MemeInteractions}from './meme-interactions.js';let trackingEnabled=false;let prefetchEnabled=false;class MemeApp{constructor(){this.display=null;this.navigation=null;this.interactions=null;this.tracking=null;this.prefetch=null;this.init();}async init(){console.log('[MemeApp] Initializing...');this.display=new MemeDisplay();this.navigation=new MemeNavigation();this.interactions=new MemeInteractions();if(trackingEnabled){const{MemeTracking}=await import('./meme-tracking.js');this.tracking=new MemeTracking();}if(prefetchEnabled){const{MemePrefetch}=await import('./meme-prefetch.js');this.prefetch=new MemePrefetch();}console.log('[MemeApp] Initialized successfully');if(window.location.hostname==='localhost'){window.memeApp=this;}}}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',()=> new MemeApp());}else{new MemeApp();}